import re, os, subprocess, collections

decls = []  # (name, path, line, recv)
for root, dirs, files in os.walk('internal'):
    for f in files:
        if not f.endswith('.go') or f.endswith('_test.go'): continue
        p = os.path.join(root,f)
        for i, line in enumerate(open(p, encoding='utf8'), 1):
            m = re.match(r'func (?:\(([^)]*)\)\s*)?([A-Za-z_]\w*)\(', line)
            if m:
                decls.append((m.group(2), p, i, m.group(1) or ''))

# gather all go files (non-test) to count call sites
gofiles = []
for root, dirs, files in os.walk('.'):
    if any(x in root for x in ('node_modules','.git','/web')): continue
    for f in files:
        if f.endswith('.go') and not f.endswith('_test.go'):
            gofiles.append(os.path.join(root,f))
contents = {p: open(p, encoding='utf8', errors='ignore').read() for p in gofiles}

counts = collections.Counter()
callerfiles = {}
for name, p, ln, recv in decls:
    pat = re.compile(r'(?<![\w.])'+re.escape(name)+r'\(')
    patq = re.compile(r'\.'+re.escape(name)+r'\(')
    n = 0; files=set()
